use glam::{DMat4,DVec3};use ingetrazo_core::{groups::Group,mesh::Mesh,scene::SelectionItem,materials::Material};use ingetrazo_gui::IngeTrazoApp;
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());
 let mut app=IngeTrazoApp::new();let mut mesh=Mesh::new();let ring=[DVec3::ZERO,DVec3::new(2.,0.,0.),DVec3::new(2.,2.,0.),DVec3::new(0.,2.,0.)].map(|p|mesh.add_vertex(p));mesh.add_face(ring.to_vec(),vec![]).unwrap();mesh.faces[0].attrs.insert("texture".into(),serde_json::json!({"uvw":[1.,0.,0.,3.,0.,2.,0.,4.],"vendor_projection":71}));mesh.faces[0].attrs.insert("color".into(),serde_json::json!([0.2,0.4,0.6,1.]));
 let source_frame=DMat4::from_translation(DVec3::new(3.,4.,5.))*DMat4::from_rotation_z(0.4)*DMat4::from_scale(DVec3::new(-2.,3.,4.));let destination_frame=DMat4::from_translation(DVec3::new(-10.,2.,1.))*DMat4::from_rotation_y(0.7)*DMat4::from_scale(DVec3::new(2.,0.5,3.));
 let mut source=Group::with_mesh("source",mesh);source.transform=source_frame;let mut destination=Group::new("destination");destination.transform=destination_frame;app.scene.groups.extend([source,destination]);ingetrazo_formats::igz::save_igz(&app.scene,&dir.join("context-source.igz")).unwrap();
 app.scene.select(SelectionItem::Group(0));app.begin_component_edit();app.scene.select(SelectionItem::Face(0));app.copy_selection();app.cancel_component_edit();app.scene.clear_selection();app.scene.select(SelectionItem::Group(1));app.begin_component_edit();let before=app.scene.clone();let depth=app.undo_stack.len();app.paste_in_place();assert_eq!(app.undo_stack.len(),depth+1);app.undo();assert_eq!(app.scene,before);app.redo();app.finish_component_edit();ingetrazo_formats::igz::save_igz(&app.scene,&dir.join("context-result.igz")).unwrap();
 std::fs::write(dir.join("context-frames.json"),serde_json::to_vec(&serde_json::json!({"source":source_frame.to_cols_array(),"destination":destination_frame.to_cols_array()})).unwrap()).unwrap();
 let mut foreign=IngeTrazoApp::new();let mut mesh=Mesh::new();let ids=[DVec3::ZERO,DVec3::X,DVec3::Y].map(|p|mesh.add_vertex(p));mesh.add_face(ids.to_vec(),vec![]);mesh.faces[0].attrs.insert("mat".into(),serde_json::json!("Paint"));mesh.faces[0].attrs.insert("texture".into(),serde_json::json!({"embed":"same.png","uvw":[1.,0.,0.,0.,0.,1.,0.,0.],"vendor_note":{"path":"same.png","material":"Paint"}}));let group=Group::with_mesh("shared",mesh);let uid=group.id;foreign.scene.groups.push(group);let definition=foreign.scene.make_component(uid).unwrap();let mut mat=Material::new("Paint",[1.,0.,0.,1.]);mat.texture_embed=Some("same.png".into());foreign.scene.materials.insert("Paint".into(),mat);foreign.scene.embedded_textures.insert("same.png".into(),vec![1,2,3]);foreign.scene.select(SelectionItem::Group(0));foreign.copy_selection();
 let mut target=IngeTrazoApp::new();target.scene.materials.insert("Paint".into(),Material::new("Paint",[0.,0.,1.,1.]));target.scene.embedded_textures.insert("same.png".into(),vec![9]);target.scene.component_definitions.insert(definition,ingetrazo_core::components::ComponentDefinition{mesh:Mesh::new(),children:vec![]});target.clipboard=foreign.clipboard.clone();let before=target.scene.clone();target.paste_in_place();assert_eq!(target.scene.groups.len(),1);let newdef=target.scene.groups[0].component_definition.unwrap();assert_ne!(newdef,definition);target.undo();assert_eq!(target.scene,before);target.redo();target.paste_in_place();assert_eq!(target.scene.groups.len(),2);assert_eq!(target.scene.groups[1].component_definition,Some(newdef));assert_ne!(target.scene.groups[0].id,target.scene.groups[1].id);assert_eq!(target.scene.embedded_textures["same.png"],vec![9]);assert_eq!(target.scene.embedded_textures["same.png (clipboard 1)"],vec![1,2,3]);assert_eq!(target.scene.materials["Paint"].color,[0.,0.,1.,1.]);assert_eq!(target.scene.materials["Paint (clipboard 1)"].color,[1.,0.,0.,1.]);
 assert_eq!(target.scene.groups[0].mesh.faces[0].attrs["texture"]["vendor_note"],serde_json::json!({"path":"same.png","material":"Paint"}),"opaque metadata must not be interpreted as resources");
 ingetrazo_formats::igz::save_igz(&target.scene,&dir.join("resources-result.igz")).unwrap();
}
